class Sensor {
  constructor(id) {
    this.id = id;
  }

  getSensorId() {
    return this.id;
  }

  readValue() {
    throw new Error("Method 'readValue()' must be implemented by subclasses.");
  }
}

class TemperatureSensor extends Sensor {
  constructor(id, unit) {
    super(id);
    this.unit = unit;
  }

  readValue() {
    return Math.floor(Math.random() * 51);
  }
}

class PressureSensor extends Sensor {
  constructor(id, maxPressure) {
    super(id);
    this.maxPressure = maxPressure;
  }

  readValue() {
    return Math.floor(Math.random() * (this.maxPressure + 1));
  }
}

// --- Test your code ---
const tempSensor = new TemperatureSensor("TS001", "Celsius");
const pressureSensor = new PressureSensor("PS002", 100);

console.log(`Temperature Sensor ${tempSensor.getSensorId()}: ${tempSensor.readValue()} ${tempSensor.unit}`);
console.log(`Pressure Sensor ${pressureSensor.getSensorId()}: ${pressureSensor.readValue()} PSI`);

try {
  const genericSensor = new Sensor("GS003");
  genericSensor.readValue();
} catch (error) {
  console.log(`Expected error caught for generic sensor: ${error.message}`);
}

